from __future__ import annotations

from dataclasses import dataclass
from typing import Mapping, Sequence


@dataclass(frozen=True)
class MilestoneSpec:
    milestone_id: str
    evidence_job_ids: tuple[str, ...]
    weight: float = 1.0


@dataclass(frozen=True)
class FrontSpec:
    front_id: str
    milestones: tuple[MilestoneSpec, ...]


@dataclass(frozen=True)
class MilestoneStatus:
    milestone_id: str
    certified: bool
    matched_job_id: str | None
    reasons: tuple[str, ...]
    weight: float


@dataclass(frozen=True)
class FrontStatus:
    front_id: str
    percent_complete: float
    certified: bool
    milestones: tuple[MilestoneStatus, ...]


@dataclass(frozen=True)
class ProgramStatus:
    percent_complete: float
    certified: bool
    fronts: tuple[FrontStatus, ...]


def _is_certified_result(result: Mapping[str, object]) -> tuple[bool, tuple[str, ...]]:
    reasons: list[str] = []
    if result.get('status') != 'INTEGRATED':
        reasons.append('STATUS_NOT_INTEGRATED')
    if result.get('certification') != 'CERTIFIED':
        reasons.append('CERTIFICATION_NOT_CERTIFIED')
    if result.get('work_completion') != 'COMPLETE':
        reasons.append('WORK_NOT_COMPLETE')
    if result.get('quality_gate') != 'PASS':
        reasons.append('QUALITY_GATE_NOT_PASS')
    if result.get('percent_complete') != 100:
        reasons.append('PERCENT_NOT_100')
    if result.get('production_touched') is not False:
        reasons.append('PRODUCTION_TOUCH_NOT_FALSE')
    blockers = result.get('blockers')
    if blockers not in (None, []):
        reasons.append('BLOCKERS_PRESENT')
    return (not reasons, tuple(reasons))


def evaluate_milestone(
    spec: MilestoneSpec,
    evidence_by_job_id: Mapping[str, Mapping[str, object]],
) -> MilestoneStatus:
    if spec.weight <= 0:
        raise ValueError('Milestone weight must be greater than zero')
    if not spec.evidence_job_ids:
        return MilestoneStatus(
            milestone_id=spec.milestone_id,
            certified=False,
            matched_job_id=None,
            reasons=('EVIDENCE_JOB_REQUIRED',),
            weight=spec.weight,
        )

    observed_reasons: list[str] = []
    for job_id in spec.evidence_job_ids:
        result = evidence_by_job_id.get(job_id)
        if result is None:
            observed_reasons.append(f'EVIDENCE_MISSING:{job_id}')
            continue
        certified, reasons = _is_certified_result(result)
        if certified:
            return MilestoneStatus(
                milestone_id=spec.milestone_id,
                certified=True,
                matched_job_id=job_id,
                reasons=(),
                weight=spec.weight,
            )
        observed_reasons.extend(f'{job_id}:{reason}' for reason in reasons)

    return MilestoneStatus(
        milestone_id=spec.milestone_id,
        certified=False,
        matched_job_id=None,
        reasons=tuple(observed_reasons),
        weight=spec.weight,
    )


def evaluate_front(
    spec: FrontSpec,
    evidence_by_job_id: Mapping[str, Mapping[str, object]],
) -> FrontStatus:
    if not spec.milestones:
        return FrontStatus(spec.front_id, 0.0, False, ())

    statuses = tuple(
        evaluate_milestone(milestone, evidence_by_job_id)
        for milestone in spec.milestones
    )
    total_weight = sum(status.weight for status in statuses)
    certified_weight = sum(status.weight for status in statuses if status.certified)
    percent = round((certified_weight / total_weight) * 100.0, 2)
    return FrontStatus(
        front_id=spec.front_id,
        percent_complete=percent,
        certified=all(status.certified for status in statuses),
        milestones=statuses,
    )


def evaluate_program(
    fronts: Sequence[FrontSpec],
    evidence_by_job_id: Mapping[str, Mapping[str, object]],
) -> ProgramStatus:
    if not fronts:
        return ProgramStatus(0.0, False, ())

    front_statuses = tuple(evaluate_front(front, evidence_by_job_id) for front in fronts)
    all_milestones = tuple(
        milestone
        for front in front_statuses
        for milestone in front.milestones
    )
    if not all_milestones:
        return ProgramStatus(0.0, False, front_statuses)

    total_weight = sum(milestone.weight for milestone in all_milestones)
    certified_weight = sum(
        milestone.weight for milestone in all_milestones if milestone.certified
    )
    percent = round((certified_weight / total_weight) * 100.0, 2)
    certified = all(front.certified for front in front_statuses)
    return ProgramStatus(percent, certified, front_statuses)

from core.bos_program_status import (
    FrontSpec,
    MilestoneSpec,
    evaluate_program,
)


def certified_result():
    return {
        'status': 'INTEGRATED',
        'certification': 'CERTIFIED',
        'work_completion': 'COMPLETE',
        'quality_gate': 'PASS',
        'percent_complete': 100,
        'production_touched': False,
        'blockers': [],
    }


def program_spec():
    return (
        FrontSpec(
            front_id='foundation',
            milestones=(
                MilestoneSpec('architecture', ('JOB-A',)),
                MilestoneSpec('canonical-data', ('JOB-B',)),
            ),
        ),
        FrontSpec(
            front_id='governance',
            milestones=(MilestoneSpec('policy', ('JOB-C',)),),
        ),
    )


def test_program_is_100_only_when_every_required_milestone_is_certified():
    evidence = {job: certified_result() for job in ('JOB-A', 'JOB-B', 'JOB-C')}
    status = evaluate_program(program_spec(), evidence)
    assert status.percent_complete == 100.0
    assert status.certified is True


def test_missing_evidence_prevents_100_and_reports_objective_progress():
    evidence = {'JOB-A': certified_result(), 'JOB-C': certified_result()}
    status = evaluate_program(program_spec(), evidence)
    assert status.percent_complete == 66.67
    assert status.certified is False
    foundation = status.fronts[0]
    assert foundation.percent_complete == 50.0
    assert foundation.certified is False


def test_pending_audit_evidence_does_not_count_as_certified():
    pending = certified_result()
    pending['certification'] = 'PENDING_AUDIT_EVIDENCE'
    evidence = {'JOB-A': pending, 'JOB-B': certified_result(), 'JOB-C': certified_result()}
    status = evaluate_program(program_spec(), evidence)
    assert status.percent_complete == 66.67
    assert status.certified is False


def test_production_touch_prevents_certification():
    touched = certified_result()
    touched['production_touched'] = True
    evidence = {'JOB-A': touched, 'JOB-B': certified_result(), 'JOB-C': certified_result()}
    status = evaluate_program(program_spec(), evidence)
    assert status.certified is False
    assert status.percent_complete == 66.67


def test_blockers_prevent_certification():
    blocked = certified_result()
    blocked['blockers'] = ['REAL_BLOCKER']
    evidence = {'JOB-A': blocked, 'JOB-B': certified_result(), 'JOB-C': certified_result()}
    status = evaluate_program(program_spec(), evidence)
    assert status.certified is False


def test_alternative_certified_evidence_can_satisfy_a_milestone():
    spec = (
        FrontSpec(
            front_id='runtime',
            milestones=(MilestoneSpec('runtime-cert', ('JOB-OLD', 'JOB-R2')),),
        ),
    )
    evidence = {'JOB-R2': certified_result()}
    status = evaluate_program(spec, evidence)
    assert status.certified is True
    assert status.fronts[0].milestones[0].matched_job_id == 'JOB-R2'


def test_empty_specs_never_claim_completion():
    status = evaluate_program((), {})
    assert status.percent_complete == 0.0
    assert status.certified is False
